mapper.update:
UPDATE vm_air_task_t SET
       `plan_id` = #{planId},
       `update_user` = #{updateUser},
       `update_time` = now()
WHERE `plan_id` = #{oldPlanId}
AND `plan_time` <= #{startTime}

mapper.select:
SELECT
    a.`id` as taskId, a.`plan_id` as planId, b.`plan_name` as planName,a.`plan_name` as taskName, a.`plan_task_id` taskRecordId, DATE_FORMAT( a.`plan_time`, '%Y-%m-%d %H:%i' ) as scheduleExecTime, DATE_FORMAT( a.`reality_time`, '%Y-%m-%d %H:%i' ) as realityTime, a.`task_status` as status, a.`create_time` createTime, a.`create_user` as createUser, a.`update_time` as updateTime,
a.fly_time,a.`update_user` as updateUser, a.`medium_status` as  mediumStatus, a.`tenant_id` as  tenantId, a.`industry_code` as industryCode, a.`access_node` as accessNode, a.`accept_node` as acceptNode, a.`is_it_enabled` as isItEnabled,fly_time as flyTime,error_reason as errorReason,break_point_json as breakPointJson,b.device_Code deviceCode,a.flight_route_id flightRouteId,l.flight_route_name as flightRouteName,
a.task_type as taskType,d.device_code as uavCode,a.delete_flag deleteFlag,l.air_mileage as airMileage,a.accumulate_mileage as accumulateMileage,
b.auto_resume,d.device_name as uavName,a.frog_leap,i.device_name as startNestName,e.device_name as endNestName
FROM vm_air_task_t a
LEFT join vm_air_plan_t b on a.plan_id = b.plan_id
LEFT JOIN vm_air_line_t l on a.flight_route_id = l.flight_route_id
LEFT JOIN vm_uav_device_info_t d ON a.uav_code = d.device_code COLLATE utf8mb4_general_ci
LEFT JOIN vm_uav_device_info_t nd ON l.device_code = nd.uav_nest_code
LEFT JOIN vm_uav_nest_device_info i on a.start_nest_code = i.device_code COLLATE utf8mb4_general_ci
LEFT JOIN vm_uav_nest_device_info e on a.end_nest_code = e.device_code COLLATE utf8mb4_general_ci
WHERE  l.flight_main_type = 0


        AND a.delete_flag in('0','1')


        and a.`delete_flag` = '0'




    AND DATE_FORMAT(a.plan_time,'%Y-%m-%d %H:%i:%s') >= #{queryTaskStartTime}


    AND DATE_FORMAT(a.plan_time,'%Y-%m-%d %H:%i:%s') <= #{queryTaskEndTime}


    AND ((b.plan_name like CONCAT('%', #{planName}, '%')
    OR EXISTS (SELECT 1 FROM vm_air_task_t t LEFT JOIN vm_air_plan_t ap ON ap.plan_id = t.plan_id WHERE t.plan_name LIKE CONCAT('%', #{planName}, '%') AND ap.plan_id = a.plan_id AND t.delete_flag = 0)))



        and ((task_status IN

            #{item}

        ) or a.is_it_enabled = 1)




        and (task_status IN

            #{item}

        )



    and b.plan_type IN

        #{item}



    and l.flight_route_name like CONCAT('%', #{flightRouteName}, '%')


    and l.flight_route_id #{flightRouteId}


    and (d.device_name like CONCAT('%', #{deviceName}, '%') or nd.device_name like CONCAT('%', #{deviceName}, '%'))


    and i.device_name like CONCAT('%', #{uavNestName}, '%')


    and b.plan_Id = #{planId}


    and a.task_type in

        #{item}



    AND DATE_FORMAT(a.reality_time,'%Y-%m-%d %H:%i:%s') >= #{realityStartTime}


    AND DATE_FORMAT(a.reality_time,'%Y-%m-%d %H:%i:%s') <= #{realityEndTime}


    and b.auto_resume = #{autoResume}


    and a.frog_leap = #{frogLeap}


    and i.device_name like CONCAT('%', #{startNestName}, '%')


    and e.device_name like CONCAT('%', #{endNestName}, '%')

${dataScope}
ORDER BY b.create_time desc

select original_Task_Record_Id as taskRecordId
from vm_air_refly_task_ref a
    left join vm_air_task_t b on a.original_Task_Record_Id = b.plan_task_id
where a.task_record_id = #{taskRecordId}
  and a.photo_id = #{photoId}

SELECT a.`plan_name` as taskName, a.`plan_task_id` taskRecordId, a.`task_status` as status, (case when length(IFNULL(rel.device_name, '')) = 0 then d.device_name else rel.device_name end ) as uavName, a.`plan_time` as scheduleExecTime, a.`reality_time` as realityTime, a.fly_time as flyTime, l.device_code as deviceCode, l.access_Node as accessNode FROM vm_air_task_t a left join vm_air_plan_t b on a.plan_id = b.plan_id LEFT JOIN vm_air_line_t l on a.flight_route_id = l.flight_route_id LEFT JOIN vm_uav_device_info_t d ON a.uav_code = d.device_code COLLATE utf8mb4_general_ci LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = d.device_code and rel.tenant_id = #{tenantId} and rel.industry_code = #{industryCode} and rel.delete_flag = '0' and rel.device_type = 1 WHERE a.`delete_flag` = 0 and a.uav_code = #{uavCode} and a.task_status IN
#{item}
and a.`plan_name` like concat('%',#{taskName},'%')
AND DATE_FORMAT(a.plan_time,'%Y-%m-%d %H:%i:%s') >= #{realityStartTime}
AND DATE_FORMAT(a.plan_time,'%Y-%m-%d %H:%i:%s') <= #{realityEndTime}
${dataScope} ORDER BY b.create_time desc

select start_nest_code
from vm_air_task_t
where plan_task_id = #{taskRecordId}
